// Self-contained Worker serving gzipped site content.
// Decompresses on-demand using DecompressionStream, then caches at edge.
const ROUTES = [{"path": "/01.html", "b64": "", "ct": "text/html; charset=utf-8", "raw": 312634, "gz": 54775}, {"path": "/02.html", "b64": "", "ct": "text/html; charset=utf-8", "raw": 20115, "gz": 7050}, {"path": "/03.html", "b64": "", "ct": "text/html; charset=utf-8", "raw": 45661, "gz": 13633}, {"path": "/04.html", "b64": "", "ct": "text/html; charset=utf-8", "raw": 14632, "gz": 5501}, {"path": "/05.html", "b64": "", "ct": "text/html; charset=utf-8", "raw": 116415, "gz": 29616}, {"path": "/06.html", "b64": "", "ct": "text/html; charset=utf-8", "raw": 63107, "gz": 16468}, {"path": "/07.html", "b64": "", "ct": "text/html; charset=utf-8", "raw": 43481, "gz": 10466}, {"path": "/08.html", "b64": "", "ct": "text/html; charset=utf-8", "raw": 78471, "gz": 18464}, {"path": "/assets/style.css", "b64": "", "ct": "text/css; charset=utf-8", "raw": 11232, "gz": 3169}, {"path": "/index.html", "b64": "", "ct": "text/html; charset=utf-8", "raw": 6882, "gz": 2663}];

export default {
  async fetch(request, env, ctx) {
    const u = new URL(request.url);
    let p = u.pathname;
    if (p === '/' || p === '') p = '/index.html';
    let entry = ROUTES.find(r => r.path === p);
    if (!entry && !p.endsWith('/')) {
      entry = ROUTES.find(r => r.path === p + '/index.html');
    }
    if (!entry) {
      return new Response('Not Found: ' + p, { status: 404, headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
    }
    // Try edge cache first
    const cache = caches.default;
    let cached = await cache.match(request);
    if (cached) return cached;
    // Decode base64 -> gzipped bytes -> decompress
    const gzStr = atob(entry.b64);
    const gzBytes = new Uint8Array(gzStr.length);
    for (let i = 0; i < gzStr.length; i++) gzBytes[i] = gzStr.charCodeAt(i);
    const ds = new DecompressionStream('gzip');
    const blob = new Blob([gzBytes]).stream().pipeThrough(ds);
    const decompressed = await new Response(blob).arrayBuffer();

    // Cache strategy: differentiate by content type for optimal China PoP caching
    const isStatic = /\.(css|js|png|jpg|jpeg|gif|svg|ico|woff2?|ttf)$/i.test(p);
    const isHtml = entry.ct.startsWith('text/html');
    let browserCache, cdnCache;
    if (isStatic) {
      // Static assets: 1 year immutable (never changes, perfect for edge caching)
      browserCache = 'public, max-age=31536000, immutable';
      cdnCache = 'public, max-age=31536000, immutable';
    } else if (isHtml) {
      // HTML pages: 1 hour + stale-while-revalidate (serve fast, refresh in background)
      browserCache = 'public, max-age=3600, stale-while-revalidate=86400';
      cdnCache = 'public, max-age=604800, stale-while-revalidate=2592000';
    } else {
      browserCache = 'public, max-age=86400, stale-while-revalidate=604800';
      cdnCache = 'public, max-age=604800, stale-while-revalidate=2592000';
    }

    const response = new Response(decompressed, {
      headers: {
        'Content-Type': entry.ct,
        'Cache-Control': browserCache,
        'CDN-Cache-Control': cdnCache,
        'Vary': 'Accept-Encoding',
        'Access-Control-Allow-Origin': '*'
      }
    });
    // Cache at edge for subsequent requests (served from nearest PoP incl. China)
    ctx.waitUntil(cache.put(request, response.clone()));
    return response;
  }
};
